      "rows": [{"label":"Side inbox","question":"Can repeated delivery replace a value?","reason":"Replay the stored reply for a redelivered event ID; record a different value for an already-admitted side as a conflict without replacing it.","source":"engine","target":"n3","fields":{"side":"left|right","value":"integer"},"invariant":"The first admitted value per side is immutable; a different value is recorded as a conflict and never changes the pair state.","kind":"store","checks":["case0","bounded-mechanism"]},{"label":"Value comparator","question":"What counts as a match?","reason":"Use exact typed scalar equality after both sides arrive.","source":"engine","target":"n4","fields":{"left":"integer","right":"integer"},"invariant":"No tolerance or missing-value default is invented.","kind":"module","checks":["case0","bounded-mechanism"]},{"label":"Result outbox","question":"Can a matching pair emit twice?","reason":"Commit terminal state and one pair-result intent atomically.","source":"n4","target":"n5","fields":{"pairId":"string","state":"matched|mismatch"},"invariant":"One key/revision produces one terminal result; a later conflict is recorded, not emitted as a second result.","kind":"store","checks":["case0","bounded-mechanism"]},{"label":"Result projection","question":"What if result delivery repeats?","reason":"Apply pair ID once, preserve the mismatch explanation and list recorded conflicts beside the result.","source":"n5","target":"n6","fields":{"pairId":"string","reason":"string"},"invariant":"A mismatch is a visible terminal outcome.","kind":"worker","checks":["case2"]},{"label":"Missing-side timer","question":"When is waiting considered overdue?","reason":"At the deadline mark a still-waiting pair overdue with its missing side, without fabricating a counterpart; a late side then resolves it to matched or mismatch.","source":"engine","target":"n7","fields":{"deadline":"timestamp","missingSide":"left|right"},"invariant":"Overdue is a visible non-terminal state, never matched.","kind":"module","checks":["case1","bounded-mechanism"]},{"label":"Reconciliation scan","question":"How are lost notifications found?","reason":"Scan durable terminal pairs against outbox/projection and repair missing publication.","source":"n6","target":"n8","fields":{"cursor":"key/revision","repairId":"uuid"},"invariant":"Repair retains the original pair identity.","kind":"worker","checks":["case3"]}],
      "code": "transaction(() => { const pair = lockPair(entityId, revision);\n if (pair.replies.has(eventId)) return pair.replies.get(eventId); // redelivery\n const prior = pair[side];\n if (prior !== undefined && prior !== value) { appendConflict(pair, side, value, eventId); return remember(pair, eventId, \"conflict\"); }\n if (prior === undefined) pair[side] = value; // an equal repeat is suppressed\n if (pair.left !== undefined && pair.right !== undefined && !pair.terminal) {\n  pair.state = pair.left === pair.right ? \"matched\" : \"mismatch\"; pair.terminal = true; insertResultUnique(pair.id, pair.state); }\n return remember(pair, eventId, pair.state); });\n// Timer: a non-terminal waiting pair past its deadline becomes overdue with missingSide; a late side then resolves it.",
